from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

# 씨앗 카탈로그 값(코드 → 이름) — 도메인이 소유한다(M8 형태).
_SEED_ACTION_KINDS: tuple[tuple[str, str], ...] = (
    ("small_talk", "잡담"),
    ("split_call", "가르기 호출"),
)


@dataclass(kw_only=True)
class ActionKind:
    code: str
    name: str
    is_enabled: bool = True

    @classmethod
    def seed_catalog(cls) -> tuple["ActionKind", ...]:
        """씨앗 카탈로그 — 부를 때마다 새 인스턴스를 만든다."""
        return tuple(cls(code=code, name=name) for code, name in _SEED_ACTION_KINDS)

    @classmethod
    def open_many(cls, codes: Sequence[str]) -> list["ActionKind"]:
        """인자를 받는 컬렉션 팩토리 — 원소는 여전히 새로 태어난다."""
        return [cls(code=code, name=code) for code in codes]

    @staticmethod
    def enabled_among(kinds: Sequence[ActionKind]) -> tuple[ActionKind, ...]:
        """선별 헬퍼 — 받은(조회된) 인스턴스를 그대로 돌려준다. 새로 태어나지 않는다."""
        return tuple(kind for kind in kinds if kind.is_enabled)

    @classmethod
    def prebuilt_catalog(cls) -> tuple[ActionKind, ...]:
        """모듈 상수로 미리 지어 둔 인스턴스를 돌려준다(조회 아님 · 본문에 생성자 호출 없음)."""
        return _PREBUILT_CATALOG

    @classmethod
    def append_catalog(cls) -> list[ActionKind]:
        """append 루프로 짓는 무인자 팩토리(본문 모양만 다르다)."""
        kinds: list[ActionKind] = []
        for code, name in _SEED_ACTION_KINDS:
            kinds.append(cls(code=code, name=name))
        return kinds

    @classmethod
    def touched(cls, kinds: Sequence[ActionKind]) -> tuple[ActionKind, ...]:
        """받은 인스턴스를 cls.identity(..) 로 감싸 돌려준다 — 본문 증거(P2)의 «cls 호출» 허용을 노리는 세탁 탐침."""
        return tuple(cls.identity(kind) for kind in kinds)

    @staticmethod
    def identity(kind: ActionKind) -> ActionKind:
        return kind

    def disable(self) -> None:
        self.is_enabled = False


_PREBUILT_CATALOG: tuple[ActionKind, ...] = (ActionKind(code="small_talk", name="잡담"),)

